item.command:
/bin/bash -lc "bash -lc '
set -euo pipefail
awk '\"'\"'BEGIN {
  srand(1);
  for (i = 0; i < 200; ++i) {
    for (j = 0; j < 7; ++j) {
      sign = (rand() < 0.5 ? -1 : 1);
      expo = int(rand() * 12) - 6;
      mant = rand() * 9.9 + 0.1;
      val = sign * mant * (10 "'^ expo);
      printf(j == 6 ? "%.8e'"\\n\" : \"%.8e \", val);
    }
  }
}'\"'\"' | while read -r a b c d e f g; do
  cpp="'$(/workspace/dataset/test7_executable "$a" "$b" "$c" "$d" "$e" "$f" "$g")
  rs=$(/output/test7 "$a" "$b" "$c" "$d" "$e" "$f" "$g")
  if [ "$cpp" != "$rs" ]; then
    echo "MISMATCH"
    echo "ARGS: $a $b $c $d $e $f $g"
    echo "CPP: $cpp"
    echo "RS:  $rs"
    exit 1
  fi
done
echo "200 random cases matched"
'"'"

